/**
 * Runs a spec-tacular test matrix against the real code, one test per row.
 *
 * Copied into the project by `spec-tacular matrix --write`, and regenerated by
 * it: do not edit. It depends on nothing, and works with any test framework
 * that takes a name and a function:
 *
 *     import { test } from 'bun:test';            // or vitest, or jest
 *     import { matrixCases } from './spec-tacular-matrix.ts';
 *     import { harness } from './harness/archive.ts';
 *     import matrix from '../../spec-tacular/matrix/archive/archive-only-closed-work.json';
 *
 *     for (const c of matrixCases(matrix, harness)) test(c.name, c.run);
 *
 * The rows say what to drive and what must come out; only the harness — how
 * to set each input in the real code and read each output from it — is
 * written by hand. A test is named with the requirement's tag and its row,
 * `[req:archive#archive-only-closed-work] [row:D7]`, so its result is
 * evidence for exactly that row.
 */

export type Value = boolean | number | string;

/** How the matrix reaches the real code. */
export interface Harness {
  /** Before each row: a fresh system. */
  reset?(): void | Promise<void>;
  /** Puts the system in the state where `name` has `value`. */
  drive(name: string, value: Value): void | Promise<void>;
  /** Reads `name` from the system, as it is now. */
  observe(name: string): Value | Promise<Value>;
  /** Advances one step, for requirements over time. */
  tick?(): void | Promise<void>;
  /**
   * Reads an input back from the system, independently of `drive`. When the
   * harness has it, every input is read back after each drive: one that
   * changed although it was not the one driven fails the row, because a row
   * that passes then passes for the wrong reason.
   */
  probe?(name: string): Value | Promise<Value>;
}

type Expr =
  | { k: 'var'; name: string }
  | { k: 'lit'; value: Value }
  | { k: 'not'; e: Expr }
  | { k: 'bin'; op: 'and' | 'or' | 'xor' | 'implies' | 'iff'; a: Expr; b: Expr }
  | { k: 'cmp'; op: '=' | '!=' | '<' | '>' | '<=' | '>='; a: Expr; b: Expr };

type Check = { kind: 'at'; step: number; holds: boolean } | { kind: 'some' | 'every' | 'none'; from: number; to: number };

interface Row {
  id: string;
  steps: Record<string, Value>[];
  expect?: Record<string, Value>;
  checks?: Check[];
  infeasible?: string;
  words: string;
}

export interface Matrix {
  tag: string;
  kind: 'decision' | 'fret';
  inputs: Record<string, string>;
  outputs: Record<string, string>;
  response?: Expr;
  rows: Row[];
  selfTest: { id: string; response: boolean[]; checks: Check[]; passes: boolean }[];
}

function value(e: Expr, env: Record<string, Value>): Value {
  if (e.k === 'lit') return e.value;
  if (e.k === 'var') return env[e.name] ?? false;
  return holds(e, env);
}

export function holds(e: Expr, env: Record<string, Value>): boolean {
  switch (e.k) {
    case 'lit': return e.value === true;
    case 'var': return env[e.name] === true;
    case 'not': return !holds(e.e, env);
    case 'bin': {
      const a = holds(e.a, env);
      const b = holds(e.b, env);
      return e.op === 'and' ? a && b : e.op === 'or' ? a || b : e.op === 'xor' ? a !== b : e.op === 'implies' ? !a || b : a === b;
    }
    case 'cmp': {
      const a = value(e.a, env);
      const b = value(e.b, env);
      if (e.op === '=') return a === b;
      if (e.op === '!=') return a !== b;
      const [x, y] = [Number(a), Number(b)];
      return e.op === '<' ? x < y : e.op === '>' ? x > y : e.op === '<=' ? x <= y : x >= y;
    }
  }
}

/** The four checks over whether the response held at each step. */
export function failedCheck(checks: Check[], response: boolean[]): Check | null {
  for (const c of checks) {
    let ok: boolean;
    if (c.kind === 'at') ok = response[c.step] === c.holds;
    else {
      const window = response.slice(c.from, c.to + 1);
      ok = c.kind === 'some' ? window.some(Boolean) : c.kind === 'every' ? window.every(Boolean) : !window.some(Boolean);
    }
    if (!ok) return c;
  }
  return null;
}

const describe = (c: Check) =>
  c.kind === 'at' ? `${c.holds ? '' : 'not '}at step ${c.step}` : `${c.kind} of steps ${c.from}–${c.to}`;

/** Drives a step's inputs; with `probe`, checks no drive moved another input. */
async function driveStep(h: Harness, row: Row, step: Record<string, Value>): Promise<void> {
  const driven: Record<string, Value> = {};
  for (const [name, v] of Object.entries(step)) {
    await h.drive(name, v);
    driven[name] = v;
    if (!h.probe) continue;
    for (const [other, want] of Object.entries(driven)) {
      const got = await h.probe(other);
      if (got !== want) {
        throw new Error(
          `${row.id}: driving ${name}=${String(v)} changed ${other} to ${String(got)} (it was set to ${String(want)}) — ` +
            'the harness drives more than one input at once, so this row would pass for the wrong reason',
        );
      }
    }
  }
}

async function runRow(matrix: Matrix, row: Row, h: Harness): Promise<void> {
  await h.reset?.();
  if (matrix.kind === 'decision') {
    await driveStep(h, row, row.steps[0] ?? {});
    for (const [name, want] of Object.entries(row.expect ?? {})) {
      const got = await h.observe(name);
      if (got !== want) throw new Error(`${row.id}: ${row.words}\n  ${name} was ${String(got)}, expected ${String(want)}`);
    }
    return;
  }
  // Over time: drive each step's inputs, read the outputs, then move on.
  const response: boolean[] = [];
  for (const step of row.steps) {
    await driveStep(h, row, step);
    const env: Record<string, Value> = { ...step };
    for (const name of Object.keys(matrix.outputs)) env[name] = await h.observe(name);
    response.push(holds(matrix.response!, env));
    await h.tick?.();
  }
  const failed = failedCheck(row.checks ?? [], response);
  if (failed) {
    const seen = response.map((r, i) => `${i}:${r ? 'T' : 'F'}`).join(' ');
    throw new Error(`${row.id}: ${row.words}\n  the response failed "${describe(failed)}"; it held at ${seen}`);
  }
}

export interface MatrixCase {
  name: string;
  run: () => Promise<void>;
}

/**
 * One case per runnable row, and one per checker self-test. A self-test
 * gives the checks a response that breaks them and one that meets them: a
 * checker that passes everything is caught here, not trusted.
 */
export function matrixCases(matrix: Matrix, harness: () => Harness): MatrixCase[] {
  const rows = matrix.rows
    .filter((r) => !r.infeasible)
    .map((row) => ({ name: `${matrix.tag} [row:${row.id}] ${row.words}`, run: () => runRow(matrix, row, harness()) }));
  const selfTests = matrix.selfTest.map((s) => ({
    name: `[spec-tacular checker] ${s.id}`,
    run: async () => {
      const passed = failedCheck(s.checks, s.response) === null;
      if (passed !== s.passes) throw new Error(`the checker said ${passed ? 'pass' : 'fail'} for ${s.id}, which must ${s.passes ? 'pass' : 'fail'}`);
    },
  }));
  return [...rows, ...selfTests];
}

// -----------------------------------------------------------------------------
// Declarative harnesses
// -----------------------------------------------------------------------------

/**
 * A harness written as data: which export to call, which field to set or
 * read. It holds no logic, so it cannot compute an answer of its own — the
 * failure a hand-written harness is most prone to. `spec-tacular matrix
 * --write` compiles `<component>.mapping.yaml` into this, next to the module
 * it maps.
 *
 * Inputs:  `arg: name`      collected into the argument object of a `call` output
 *          `set: path`      assigned on the instance
 *          `call: method`   called on the instance with the value
 *          `on_rise: method` called when it becomes true; `on_fall` when false
 * Outputs: `call: export`   the module's export, or the instance's method,
 *                           called with the collected arguments; `field` reads
 *                           one field of what it returns
 *          `read: path`     a field of the instance
 * Both:    `probe: path`    a field of the instance that reads the input back
 */
export interface Mapping {
  /** An export of the module constructed once per row (`new Client()`). */
  create?: string;
  /** An instance method called to advance one step. */
  tick?: string;
  inputs: Record<string, { arg?: string; set?: string; call?: string; on_rise?: string; on_fall?: string; probe?: string }>;
  outputs: Record<string, { call?: string; field?: string; read?: string }>;
}

const get = (o: unknown, path: string): unknown =>
  path.split('.').reduce<unknown>((x, k) => (x as Record<string, unknown> | undefined)?.[k], o);

function set(o: Record<string, unknown>, path: string, value: unknown): void {
  const keys = path.split('.');
  const last = keys.pop()!;
  const target = keys.reduce<Record<string, unknown>>((x, k) => x[k] as Record<string, unknown>, o);
  target[last] = value;
}

/** A harness that does exactly what its mapping says, and nothing else. */
export function harnessFromMapping(mapping: Mapping, mod: Record<string, unknown>): () => Harness {
  return () => {
    let instance: Record<string, unknown> | null = null;
    let args: Record<string, Value> = {};
    let last: Record<string, Value> = {};
    const fn = (name: string): ((...a: unknown[]) => unknown) => {
      const f = (instance && typeof instance[name] === 'function' ? (instance[name] as Function).bind(instance) : mod[name]) as unknown;
      if (typeof f !== 'function') throw new Error(`the mapping names ${name}, which is not a function of the module or the instance`);
      return f as (...a: unknown[]) => unknown;
    };
    return {
      reset: () => {
        args = {};
        last = {};
        if (mapping.create) {
          const Ctor = mod[mapping.create] as (new () => Record<string, unknown>) | undefined;
          if (typeof Ctor !== 'function') throw new Error(`the mapping creates ${mapping.create}, which the module does not export`);
          instance = new Ctor();
        }
      },
      drive: async (name, value) => {
        const m = mapping.inputs[name];
        if (!m) throw new Error(`the mapping has no input ${name}`);
        if (m.arg) args[m.arg] = value;
        if (m.set) set(instance ?? (mod as Record<string, unknown>), m.set, value);
        if (m.call) await fn(m.call)(value);
        if (m.on_rise && value === true && last[name] !== true) await fn(m.on_rise)();
        if (m.on_fall && value === false && last[name] === true) await fn(m.on_fall)();
        last[name] = value;
      },
      observe: async (name) => {
        const m = mapping.outputs[name];
        if (!m) throw new Error(`the mapping has no output ${name}`);
        if (m.read) return get(instance, m.read) as Value;
        const result = await fn(m.call!)({ ...args });
        return (m.field ? get(result, m.field) : result) as Value;
      },
      tick: mapping.tick ? async () => { await fn(mapping.tick!)(); } : undefined,
      // Only a real read-back counts; an input without one reads as driven.
      probe: Object.values(mapping.inputs).some((i) => i.probe)
        ? async (name) => {
            const m = mapping.inputs[name]!;
            return m.probe ? (get(instance, m.probe) as Value) : last[name]!;
          }
        : undefined,
    };
  };
}
